<script>document.querySelectorAll('.date-preset').forEach(button=>button.addEventListener('click',()=>{const form=document.getElementById('report-filters'),end=new Date(),start=new Date();if(button.dataset.preset==='month')start.setDate(1);else start.setDate(end.getDate()-Number(button.dataset.days));const fmt=date=>{const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`};form.start_date.value=fmt(start);form.end_date.value=fmt(end);form.submit()}));</script>
